ee:message.ee:set-payload:
%dw 2.0
output application/json skipNullOn = "everywhere"
---
{
	basePath: p("zsmart-sapi.base-path"),
	host: p("zsmart-sapi.host"),
	port: p("zsmart-sapi.port"),
	method: "GET",
	path: p('zsmart-sapi.resources.billingAccountItem.path'),
	body: {
	},
	headers: vars.billingHeaders default {
	},
	queryParameters: {
		"msisdn": vars.billingParams.'CONNECTION_NUMBER',
		"accountNumber": vars.billingParams.'BILLING_ACCOUNT',
		"billNumber": vars.billingParams.'INVOICE_NUMBER',
		"channelCode": vars.billingParams.'ORIGIN'
	},
	uriParameters: {
	}
}

%dw 2.0
output application/json
---
{
	"codeResponse": "200",
	"messageResponse": "OK",
	"accounts": [{
		"accountNumber": vars.billingAccount,
		"items": [(payload.result.result.billAcctItemDto update {
			case pb at .preBalance -> {
				"value": if ( !isEmpty(pb) and isInteger(pb) ) pb
              else
                "0",
				"formatted": if ( !isEmpty(pb) and isInteger(pb) ) pb as Number as String {
					format: "\$#,##0.00"
				}
              else
                "0" as Number as String {
					format: "\$#,##0.00"
				}
			}
          case due at .due -> {
				"value": if ( !isEmpty(due) and isInteger(due) ) due
              else
                "0",
				"formatted": if ( !isEmpty(due) and isInteger(due) ) due as Number as String {
					format: "\$#,##0.00"
				}
              else
                "0" as Number as String {
					format: "\$#,##0.00"
				}
			}
          case ac at .adjustCharge -> {
				"value": if ( !isEmpty(ac) and isInteger(ac) ) ac
              else
                "0",
				"formatted": if ( !isEmpty(ac) and isInteger(ac) ) ac as Number as String {
					format: "\$#,##0.00"
				}
              else
                "0" as Number as String {
					format: "\$#,##0.00"
				}
			}
          case dc at .disputeCharge -> {
				"value": if ( !isEmpty(dc) and isInteger(dc) ) dc
              else
                "0",
				"formatted": if ( !isEmpty(dc) and isInteger(dc) ) dc as Number as String {
					format: "\$#,##0.00"
				}
              else
                "0" as Number as String {
					format: "\$#,##0.00"
				}
			}
          case rc at .recvCharge -> {
				"value": if ( !isEmpty(rc) and isInteger(rc) ) rc
              else
                "0",
				"formatted": if ( !isEmpty(rc) and isInteger(rc) ) rc as Number as String {
					format: "\$#,##0.00"
				}
              else
                "0" as Number as String {
					format: "\$#,##0.00"
				}
			}
          case li at .acctItemFeeDtoList -> li map ((item, index) -> item update {
				case chrg at .charge -> {
					"value": if ( !isEmpty(chrg) and isInteger(chrg) ) chrg
                  else
                    "0",
					"formatted": if ( !isEmpty(chrg) and isInteger(chrg) ) chrg as Number as String {
						format: "\$#,##0.00"
					}
                  else
                    "0" as Number as String {
						format: "\$#,##0.00"
					}
				}
			})
		}) mapObject (v, k) -> {
			(if ( k as String == "acctItemFeeDtoList" ) "lineItems" else k): v
		}]
	}]
}

%dw 2.0
output application/json
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: p('mongo-db-sapi.resources.dynamicQuery.base-path'),
	body: {
		"query": {
			"aggregate": "MDM_CUENTA_FACTURACION",
			"pipeline": [{
				"\$match": {
					"Tipo_Documento": vars.billingParams.'CUSTOMER_ID_TYPE',
					"Numero_Identificacion": vars.billingParams.'CUSTOMER_ID'
				}
			}],
			"cursor": {
			}
		}
	},
	headers: vars.billingHeaders default {
	},
	queryParameters: {
	},
	uriParameters: {
	}
}

