%dw 2.0
output application/json
---
{
    "status": "400",
    "code": "BILLING_ACCOUNT_ITEM:INVALID_PARAMS",
    "message": "At least 'BILLING_ACCOUNT' or both 'CUSTOMER_ID_TYPE' and 'CUSTOMER_ID' must be provided.",
    "messageServer": error.description,
    "cause": [
        {
            "origin": "customer-papi-services-v2",
            "message": "At least 'BILLING_ACCOUNT' or both 'CUSTOMER_ID_TYPE' and 'CUSTOMER_ID' must be provided."
        }
    ]
}
